import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        int n = Integer.parseInt(br.readLine());
        String s = br.readLine() + "_";

        boolean insideParentheses = false, insideWord = false;
        int totalWords = 0, currentWordLength = 0, maxWordLength = 0;

        for (int i = 0; i <= n; i++) {
            char c = s.charAt(i);
            if (insideWord && (c == '_' || c == '(' || c == ')')) {
                insideWord = false;
                if (insideParentheses) {
                    totalWords++;
                } else if (currentWordLength > maxWordLength) {
                    maxWordLength = currentWordLength;
                }
                if (c == '(') {
                    insideParentheses = true;
                }
                if (c == ')') {
                    insideParentheses = false;
                }
                currentWordLength = 0;
            } else if (!insideWord && !(c == '_' || c == '(' || c == ')')) {
                insideWord = true;
                currentWordLength++;
            } else if (insideWord) {
                currentWordLength++;
            } else {
                if (c == '(') {
                    insideParentheses = true;
                } else if (c == ')') {
                    insideParentheses = false;
                }
            }
        }
        out.printf("%d %d", maxWordLength, totalWords);
        out.close();
    }
}
